package io.baozhu.atlas.api; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/metrics") public class MetricsController {private final JdbcTemplate jdbc;public MetricsController(JdbcTemplate j){jdbc=j;} @GetMapping("/overview") public Map<String,Object> overview(){long runs=jdbc.queryForObject("SELECT COUNT(*) FROM pipeline_run",Long.class);long success=jdbc.queryForObject("SELECT COUNT(*) FROM pipeline_run WHERE status='SUCCESS'",Long.class);long tasks=jdbc.queryForObject("SELECT COUNT(*) FROM task_run",Long.class);return Map.of("runs",runs,"successfulRuns",success,"successRate",runs==0?1.0:(double)success/runs,"taskRuns",tasks);}}
